from datetime import datetime, timedelta

# Symbolic constants to replace magic numbers
SLOT_DURATION_MINUTES = 60
DAY_START_HOUR = 0
DAY_START_MINUTE = 0
DAY_END_HOUR = 23
DAY_END_MINUTE = 59

class CalendarUtil:
    def __init__(self):
        self._events = []

    @property
    def events(self):
        return list(self._events)

    def _set_events(self, events):
        self._events = list(events)

    # Encapsulate Field: events is now a private field with public accessors
    events = property(events, _set_events)

    def add_event(self, event):
        self._events.append(event)

    def remove_event(self, event):
        if event in self._events:
            self._events.remove(event)

    def _is_event_on_date(self, event, date):
        return event['date'].date() == date.date()

    def get_events(self, date):
        return [event for event in self._events if self._is_event_on_date(event, date)]

    def _is_event_conflicting(self, event, start_time, end_time):
        return start_time < event['end_time'] and end_time > event['start_time']

    def is_available(self, start_time, end_time):
        return not any(self._is_event_conflicting(event, start_time, end_time) for event in self._events)

    def _create_slot(self, start_time):
        end_time = start_time + timedelta(minutes=SLOT_DURATION_MINUTES)
        return (start_time, end_time)

    def _is_slot_available(self, slot):
        start_time, end_time = slot
        return self.is_available(start_time, end_time)

    def get_available_slots(self, date):
        start_time = datetime(date.year, date.month, date.day, DAY_START_HOUR, DAY_START_MINUTE)
        end_of_day = datetime(date.year, date.month, date.day, DAY_END_HOUR, DAY_END_MINUTE)

        slots = []
        current_start = start_time
        while current_start < end_of_day:
            slot = self._create_slot(current_start)
            if self._is_slot_available(slot):
                slots.append(slot)
            current_start += timedelta(minutes=SLOT_DURATION_MINUTES)

        return slots

    def _is_event_upcoming(self, event, now):
        return event['start_time'] >= now

    def get_upcoming_events(self, num_events):
        now = datetime.now()
        upcoming = [event for event in self._events if self._is_event_upcoming(event, now)]
        return upcoming[:num_events]
